// Universal loader for Cinema 3D Rust WebAssembly
window.CINEMA_3D_WASM_B64 = "";

window.initRustCinema3D = async function(canvas, fov) {
  if (typeof wasm_bindgen === 'undefined') {
    throw new Error('wasm_bindgen is not defined. Ensure cinema_3d.js is loaded.');
  }
  try {
    await wasm_bindgen('assets/wasm/cinema_3d_bg.wasm');
  } catch (err) {
    console.warn('Network wasm fetch failed, falling back to embedded binary:', err);
    var raw = atob(window.CINEMA_3D_WASM_B64);
    var bytes = new Uint8Array(raw.length);
    for (var i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
    await wasm_bindgen(bytes.buffer);
  }
  var fovVal = (typeof fov === 'number') ? fov : 0.4;
  return new wasm_bindgen.Cinema3DRenderer(canvas, fovVal);
};
